style.css:
@-moz-document domain("roblox.com") {
/* Add a custom background image from Pinterest */
  body {
    background: url('https://i.pinimg.com/736x/2f/0a/72/2f0a72f8a48cb0c783c7f9753a8c6612.jpg') no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important; /* Ensure text is readable */
  }

  /* Make inner containers semi-transparent */
  .container, .game-card-container, .navbar, .footer {
    background-color: rgba(0, 0, 0, 0.8) !important; /* Black with 80% opacity */
    color: #ffffff !important;
  }

  /* Style the navigation bar */
  .navbar {
    background-color: #800000 !important; /* Dark gray */
    border-bottom: 2px solid #800000w !important; /* Green border */
  }

  /* Style navigation bar links */
  .navbar a {
    color: #ffffff !important; /* Green links */
    font-weight: bold;
  }

  .navbar a:hover {
    color: #66bb6a !important; /* Lighter green on hover */
  }
}
